    </div>
    <div class="qr" role="img" aria-label="<?= e_attr($view->t('admin.two_factor.qr_label')) ?>"><?= $qrSvg /* SVG markup generated server-side from the otpauth URI; contains no user input beyond the escaped email */ ?></div>
    <div class="card-intro card-intro--flush">
      <span class="muted"><?= e($view->t('admin.two_factor.manual_key')) ?></span>
