      <div class="actions"><?= $view->component('button', ['label' => $view->t('admin.actions.cancel'), 'variant' => 'admin-secondary', 'href' => $adminPath . '/security']) ?><?= $view->component('button', ['label' => $view->t('admin.two_factor.activate'), 'variant' => 'admin-primary', 'type' => 'submit', 'icon' => 'fa-solid fa-check', 'iconPosition' => 'start']) ?></div>
